"""The published edition (edition/) is generated by `python -m rcodes publish`.

These tests fail when the committed edition is stale, when a chapter digest outgrows its
token budget, or when a rule is missing from (or duplicated in) the digests or element packs.
Element packs over budget only warn.
"""

from __future__ import annotations

import re
import warnings
from pathlib import Path

import pytest

from rcodes.core import publish
from rcodes.core.registry import Registry

EDITION = publish.REPO_ROOT / "edition"


def _managed_files(root: Path) -> dict[str, bytes]:
    out: dict[str, bytes] = {}
    for name in publish.MANAGED_FILES:
        p = root / name
        if p.exists():
            out[name] = p.read_bytes()
    for d in publish.MANAGED_DIRS:
        base = root / d
        if base.exists():
            for p in sorted(base.rglob("*")):
                if p.is_file():
                    out[p.relative_to(root).as_posix()] = p.read_bytes()
    return out


@pytest.fixture(scope="module")
def registry() -> Registry:
    return Registry.load(strict=False)


@pytest.fixture(scope="module")
def fresh(registry, tmp_path_factory) -> Path:
    out = tmp_path_factory.mktemp("edition")
    ed = publish.publish(registry, out)
    assert not ed.unplaced, ed.unplaced
    return out


def test_edition_is_committed():
    assert (EDITION / "README.md").exists(), "edition/ missing: run `python -m rcodes publish`"


def test_edition_is_current(fresh):
    committed = _managed_files(EDITION)
    regenerated = _managed_files(fresh)
    missing = sorted(set(regenerated) - set(committed))
    extra = sorted(set(committed) - set(regenerated))
    changed = sorted(k for k in set(regenerated) & set(committed) if regenerated[k] != committed[k])
    assert not (missing or extra or changed), (
        "edition/ is stale; run `python -m rcodes publish`. "
        f"missing {missing[:5]}, extra {extra[:5]}, changed {changed[:5]}"
        f" ({len(missing)}/{len(extra)}/{len(changed)})")


@pytest.mark.parametrize("ch", publish.CHAPTERS)
def test_digest_budget(ch):
    size = publish.tokens((EDITION / "chapters" / ch / "digest.md").read_bytes())
    assert size <= publish.DIGEST_FAIL_TOKENS, f"{ch} digest is {size} tokens (limit {publish.DIGEST_FAIL_TOKENS})"
    if size > publish.DIGEST_TARGET_TOKENS[1]:
        warnings.warn(f"{ch} digest is {size} tokens, above the {publish.DIGEST_TARGET_TOKENS[1]} target")


def test_element_pack_budget():
    packs = sorted((EDITION / "elements").rglob("*.md"))
    assert packs
    over = []
    for p in packs:
        size = publish.tokens(p.read_bytes())
        if size > publish.PACK_TARGET_TOKENS[1]:
            over.append(f"{p.relative_to(EDITION).as_posix()} ({size})")
    if over:
        warnings.warn(f"{len(over)} element packs above {publish.PACK_TARGET_TOKENS[1]} tokens: " + ", ".join(over))


def test_entry_budget():
    assert publish.tokens((EDITION / "README.md").read_bytes()) <= 2500


@pytest.mark.parametrize("ch", publish.CHAPTERS)
def test_every_rule_placed_once(registry, ch):
    """Lint: each rule ID is on exactly one digest line and heads exactly one provision in one pack;
    each fallback heads exactly one block in one pack."""
    pkg = registry.package(publish.VERSION, ch)
    digest = (EDITION / "chapters" / ch / "digest.md").read_text(encoding="utf-8")
    digest_ids = re.findall(r"^- `([^`]+)`", digest, re.M)
    pack_ids: list[str] = []
    fallback_ids: list[str] = []
    for p in sorted((EDITION / "elements" / ch).glob("*.md")):
        text = p.read_text(encoding="utf-8")
        pack_ids += re.findall(r"^### `([^`]+)`", text, re.M)
        fallback_ids += re.findall(r"^## (?:Merit assessment|Element objectives|Design guidance) `([^`]+)`", text, re.M)
    rule_ids = {publish.short_id(r.id) for r in pkg.rules.values()}
    problems = [f"{s}: digest {digest_ids.count(s)}, pack {pack_ids.count(s)}" for s in sorted(rule_ids)
                if digest_ids.count(s) != 1 or pack_ids.count(s) != 1]
    problems += [f"unknown id in digest or pack: {s}" for s in sorted(set(digest_ids + pack_ids) - rule_ids)]
    problems += [f"{publish.short_id(f.id)}: fallback blocks {fallback_ids.count(publish.short_id(f.id))}"
                 for f in pkg.fallbacks.values() if fallback_ids.count(publish.short_id(f.id)) != 1]
    assert not problems, problems


def test_chapter1_operation_layer():
    op = EDITION / publish.CH1_OPERATION
    assert op.exists(), "edition/chapters/ch1/operation.md missing"
    text = op.read_text(encoding="utf-8")
    for head in ("Table 1.1", "Figure 2.1", "Table 2.4", "Clause 2.5.2"):
        assert f"## {head}" in text, head
    assert publish.tokens(op.read_bytes()) <= publish.CH1_OPERATION_TOKENS
    perm = EDITION / publish.CH1_PERMISSIONS
    body = perm.read_text(encoding="utf-8") if perm.exists() else text
    for ch in publish.CHAPTERS:
        assert f"({ch})" in body, f"no permission table for {ch}"


def test_packs_have_local_variation_and_facts_lines():
    for p in sorted((EDITION / "elements").rglob("*.md")):
        text = p.read_text(encoding="utf-8")
        assert "\nLocal variation (Chapter 1): " in text, p.name
        lines = text.splitlines()
        for i, line in enumerate(lines):
            if line.startswith("### `"):
                assert lines[i + 2].startswith("Facts: "), f"{p.relative_to(EDITION).as_posix()}: {line}"


@pytest.mark.parametrize("ch", publish.CHAPTERS)
def test_digest_titles_readable_and_distinct(ch):
    digest = (EDITION / "chapters" / ch / "digest.md").read_text(encoding="utf-8")
    assert not re.search(r"\b(bdy|setbk|dwg|pkg|bldg)\b", digest)
    for section in digest.split("\n## ")[1:]:
        titles = [m.group(1).lower() for m in re.finditer(r"^- `[^`]+` ([^;]*);", section, re.M)]
        dups = sorted({t for t in titles if titles.count(t) > 1})
        assert not dups, f"{ch} {section.splitlines()[0]}: {dups}"


def test_skill_present():
    skill = EDITION / publish.SKILL
    assert skill.exists(), "edition/SKILL.md missing"
    text = skill.read_text(encoding="utf-8")
    assert text.startswith("---\nname: rcodes-draft-assessment\ndescription: ")
    for head in ("Mode 1", "Mode 2", "Report format", "Worked excerpt", "Limits"):
        assert head in text, head
    assert publish.tokens(skill.read_bytes()) <= 3500
    for entry in ("README.md", "CLAUDE.md", "llms.txt"):
        assert publish.SKILL in (EDITION / entry).read_text(encoding="utf-8"), entry


def test_topics_index():
    text = (EDITION / publish.TOPICS).read_text(encoding="utf-8")
    for name in ("garage", "carport", "street setback", "boundary wall", "site cover", "parking", "visitor parking",
                 "tree", "deep soil", "privacy and overlooking", "overshadowing", "fence", "driveway", "storage",
                 "waste and bins"):
        assert f"\n## {name}\n" in text, name
    garage = text.split("\n## garage\n", 1)[1].split("\n## ", 1)[0]
    for ch in ("ch2", "ch3", "ch4p1"):
        assert f"- {ch}: " in garage and "C3.3.3" in garage
    assert publish.TOPICS in (EDITION / "llms.txt").read_text(encoding="utf-8")


def test_readme_and_claude_agree_on_local_variation():
    pointer = publish.LOCAL_VARIATION_POINTER.format(perm=publish.CH1_PERMISSIONS, op=publish.CH1_OPERATION)
    for entry in ("README.md", "CLAUDE.md"):
        assert pointer in (EDITION / entry).read_text(encoding="utf-8"), entry


def test_packs_explain_rounding():
    for p in sorted((EDITION / "elements").rglob("*.md")):
        text = p.read_text(encoding="utf-8")
        for tail, words in publish.ROUNDING_WORDS:
            assert text.count(tail) == text.count(f"{tail} ({words})"), (p.name, tail)


def test_local_variation_shows_each_row_condition():
    text = (EDITION / "elements" / "ch4p1" / "2.3.md").read_text(encoding="utf-8")
    assert "C2.3.1 (row 1 of 2): regional local governments only (no printed condition)" in text
    assert "C2.3.1 (row 2 of 2): without WAPC approval (Where reducing" in text


def test_governance_present_and_linked():
    gov = EDITION / publish.GOVERNANCE
    assert gov.exists(), "edition/GOVERNANCE.md missing"
    assert gov.name not in publish.MANAGED_FILES, "GOVERNANCE.md is hand-written, not generated"
    text = gov.read_text(encoding="utf-8")
    for phrase in ("draft-2026-10-24", "replaces", "../CHANGELOG.md", "Licence: code under the MIT License",
                   "not planning advice"):
        assert phrase in text, phrase
    assert publish.tokens(gov.read_bytes()) <= 1600
    for entry in ("README.md", "CLAUDE.md", "llms.txt"):
        assert publish.GOVERNANCE in (EDITION / entry).read_text(encoding="utf-8"), entry
